{ title: "绿萝成精", mood: { name: "绿植战士", emo: "playful", pts: 2, min: 120 }, lines: ["# 我养的绿萝，已经占领了客厅", "> 它是不是想吃了你", "> 它在你睡觉时，悄悄长大", "> 请检查你的窗帘是不是被缠了", "哈哈，好像真的长了一米", "我家那盆，只会黄叶子"] },
{ title: "二手淘宝", mood: { name: "捡漏成功", emo: "energized", pts: 2, min: 150 }, lines: ["# 二手捡漏：五十块淘到大牌包", "> 我淘到了，是个钱包形状的抹布", "> 我淘到了，闻着有点潮", "> 但五十块嘛，值得", "我也想淘一个，捡漏多爽", "先看看店主信誉，别被坑"] },
{ title: "半夜刷到焦虑", mood: { name: "夜猫惊魂", emo: "tense", pts: 2, min: 120 }, lines: ["# 同龄人都买房了，你还在租房？", "> 同龄人，在租房", "> 同龄人，在家啃老", "> 同龄人，在刷这条笔记", "这种标题就是想让人焦虑", "关上手机，今晚先睡个好觉"] },
{ title: "烘焙失败集", mood: { name: "黑暗料理", emo: "playful", pts: 2, min: 120 }, lines: ["# 新手烘焙，一次成功的曲奇", "> 我烤的，是黑色圆盘", "> 我烤的，是个火山", "> 我烤的，是烟雾报警器的朋友", "我也烤过，一个冒烟的故事", "最后点了外卖，圆满结束"] },
{ title: "健身房办卡", mood: { name: "办卡仪式", emo: "confident", pts: 2, min: 120 }, lines: ["# 办了健身卡，我就是健身人了", "> 办卡等于瘦了十斤", "> 我的卡，在钱包里一年了", "> 钱包：我也瘦了", "办卡的钱，其实是买心理安慰", "安慰也是一种投资吧"] },
{ title: "晒娃晒猫", mood: { name: "吸猫日常", emo: "happy", pts: 3, min: 150 }, lines: ["# 我家猫猫今天又干了件好事", "> 它把杯子推下桌了", "> 好事？ 对它来说是", "> 它是在做实验，验证重力", "这猫真是物理学家", "我家没猫，那我自己推个杯子"] },
{ title: "诗和远方", mood: { name: "出走半日", emo: "inspired", pts: 3, min: 180 }, lines: ["# 辞职去大理，我过上了向往的生活", "> 一年后她回来上班了", "> 但她说那一年是真的好", "> 有一年好，也值了", "我也想去，哪怕一周", "先攒够假期，再出发"] },
{ title: "盲目跟风", mood: { name: "追热点", emo: "bored", pts: 1, min: 120 }, lines: ["# 这个爆款，你买了吗？", "> 买了，三天就不新鲜了", "> 买了，现在在朋友圈卖二手", "> 我没买，我是时尚落伍者", "热点来得快，去得也快", "我继续看我的老剧吧"] },
{ title: "做个手工灯", mood: { name: "光之匠人", emo: "focused", pts: 3, min: 180 }, lines: ["# 废物利用，自制氛围小夜灯", "> 我用了个酸奶瓶", "> 我用了个鞋盒，亮了", "> 然后我点着了鞋盒", "手工有风险，操作需谨慎", "今晚试试，小心一点"] },
{ title: "撒娇的力量", mood: { name: "软萌攻击", emo: "flirty", pts: 2, min: 120 }, lines: ["# 恋爱小技巧：会撒娇的人更幸福", "> 我撒娇，他说你声音怎么了", "> 我撒娇，猫跑掉了", "> 撒娇是一门艺术，我还没毕业", "我对着镜子试了一句", "嗯，自己先被肉麻到了"] },
{ title: "年终总结", mood: { name: "年末复盘", emo: "sad", pts: 2, min: 150 }, lines: ["# 年终总结：这一年我成长了", "> 我成长了，体重", "> 我成长了，焦虑", "> 我成长了，头发在减少", "又是一年，什么都没留住", "好吧，至少还留着自己"] },
{ title: "外卖退款", mood: { name: "讨回公道", emo: "angry", pts: 2, min: 120 }, lines: ["# 外卖漏了菜，商家说你自己吃了", "> 我也被这么说过", "> 退款成功的人，请举手", "> 我的手还没举起来，就被拒了", "怎么会有这样的商家", "留好截图，一定要追到底"] },
{ title: "云养花", mood: { name: "花花世界", emo: "inspired", pts: 2, min: 150 }, lines: ["# 阳台小花园，四季都有花", "> 我阳台只有晾衣架", "> 我阳台，被邻居的衣服占领", "> 你可以在衣服上画花", "我也想有朵花，哪怕一朵", "明天去花市，抱一盆回来"] },
{ title: "起床困难户", mood: { name: "与被窝为伍", emo: "bored", pts: 1, min: 120 }, lines: ["# 起床困难户的自救指南", "> 我定了十个闹钟，全关了", "> 我把闹钟放在对面，我爬过去关", "> 然后我又爬回来睡了", "起床这件事，意志力不够用", "再睡五分钟，真的只要五分钟"] },
{ title: "云旅游", mood: { name: "足不出户", emo: "dazed", pts: 1, min: 120 }, lines: ["# 在家云旅游，也能环游世界", "> 我环游了冰箱、沙发、床", "> 我的世界，不超过三十平", "> 但我的想象力很大", "我也刷了一圈风景视频", "刷完发现，窗外的树也不赖"] },
{ title: "买书不读", mood: { name: "书山有路", emo: "embarrassed", pts: 1, min: 90 }, lines: ["# 书架整理：我的买书不读收藏", "> 买书如山倒，读书如抽丝", "> 我的书，大部分是新的", "> 我的书，大部分是香的", "我也有一整架没拆封的书", "它们在等我，也在等灰"] },
{ title: "快递堆成山", mood: { name: "拆家快乐", emo: "happy", pts: 2, min: 120 }, lines: ["# 拆快递的快乐，谁懂啊", "> 拆的时候超开心，拆完就忘了买啥", "> 快递盒子比东西值钱", "> 我家猫更爱盒子", "我也爱拆，像开盲盒", "盒子留给猫，东西留给我"] }
